package io.waves

import androidx.compose.ui.graphics.painter.BitmapPainter
import androidx.compose.ui.graphics.painter.Painter
import androidx.compose.ui.res.loadImageBitmap

/**
 * Window/dock icon, loaded from `desktopMain/resources/waves-icon.png` (generated by `art/IconGen.java`).
 * The packaged .app uses `composeApp/icons/waves.icns` instead; this covers `./gradlew run` and the window icon.
 */
internal val appIcon: Painter? by lazy {
    AppIcon::class.java.getResourceAsStream("/waves-icon.png")?.use { BitmapPainter(loadImageBitmap(it)) }
}

private object AppIcon
